import { MissingPropertyException } from './missing-property-exception';
import { TypeMismatchException } from './type-mismatch-exception';

function map<T extends { [key: string]: any }>(source: { [key: string]: any }, target: T, propertyName: string): void {
    if (!source.hasOwnProperty(propertyName)) {
        throw new MissingPropertyException(propertyName);
    }

    const sourceValue = source[propertyName];
    const sourceType = typeof sourceValue;
    const targetType = typeof target[propertyName];

    if (sourceType !== targetType) {
        throw new TypeMismatchException(propertyName, sourceType, targetType);
    }

    target[propertyName as keyof T] = sourceValue;
}

export function mapAndValidate<T extends object>(source: object, target: T): void {
    const propertyNames: string[] = Object.getOwnPropertyNames(target);

    for (const propertyName of propertyNames) {
        if ((target as any)[propertyName] !== undefined) {
            map(source, target, propertyName);
        }
    }
}
